USE `booking_db`;
CREATE TABLE `approval_record` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `booking_id` BIGINT UNSIGNED NOT NULL COMMENT '预约 ID', `approver_id` BIGINT UNSIGNED NOT NULL COMMENT '审批人', `action` VARCHAR(20) NOT NULL COMMENT 'APPROVE=通过 REJECT=驳回', `comment` VARCHAR(500) DEFAULT NULL COMMENT '审批意见', `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_booking` (`booking_id`), KEY `idx_approver` (`approver_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='审批记录表';
CREATE TABLE `violation_record` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL COMMENT '违约用户', `booking_id` BIGINT UNSIGNED NOT NULL COMMENT '关联预约', `violation_type` VARCHAR(30) NOT NULL COMMENT 'NO_SHOW=未到 LATE_CANCEL=晚取消', `score_change` INT NOT NULL COMMENT '信用分变动，负数表示扣分', `remark` VARCHAR(200) DEFAULT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_booking_type` (`booking_id`,`violation_type`), KEY `idx_user_time` (`user_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='违约记录表';
CREATE TABLE `blacklist` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户', `reason` VARCHAR(200) NOT NULL COMMENT '拉黑原因', `start_date` DATE NOT NULL COMMENT '生效日期', `end_date` DATE NOT NULL COMMENT '解除日期', `operator_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '操作人，系统自动为 NULL', `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_user_end` (`user_id`,`end_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='黑名单表';
CREATE TABLE `notification` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL COMMENT '接收人', `title` VARCHAR(100) NOT NULL, `content` VARCHAR(1000) NOT NULL, `type` VARCHAR(30) NOT NULL COMMENT 'BOOKING_APPROVED / REMIND / VIOLATION 等', `biz_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '关联业务 ID，用于点击跳转', `is_read` TINYINT NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_user_read_time` (`user_id`,`is_read`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站内通知表';
CREATE TABLE `operation_log` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '操作人，未登录为 NULL', `module` VARCHAR(50) NOT NULL COMMENT '模块名', `operation` VARCHAR(100) NOT NULL COMMENT '操作描述', `method` VARCHAR(200) DEFAULT NULL COMMENT '类名.方法名', `params` TEXT COMMENT '请求参数 JSON', `ip` VARCHAR(50) DEFAULT NULL, `cost_ms` BIGINT DEFAULT NULL COMMENT '耗时（毫秒）', `success` TINYINT NOT NULL DEFAULT 1, `error_msg` VARCHAR(1000) DEFAULT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_user_time` (`user_id`,`created_at`), KEY `idx_created_at` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志表';
